{"command":"$ErrorActionPreference='Stop'; $repo='edburns/dd-3068633-win32-x64-04'; $branch='copilot/experimentshepherd-control'; $pr=5
$runsRaw=gh run list -R $repo --branch $branch --json databaseId,conclusion; $listExit=$LASTEXITCODE
if ($listExit -ne 0) { throw "Failed to list workflow runs (exit $listExit)." }
$runs=$runsRaw | ConvertFrom-Json
$pending=@($runs | Where-Object { $_.conclusion -eq 'action_required' })
foreach ($run in $pending) {
  $ok=$false
  for ($attempt=1; $attempt -le 3 -and -not $ok; $attempt++) {
    gh run rerun $run.databaseId -R $repo; $rerunExit=$LASTEXITCODE
    if ($rerunExit -eq 0) { $ok=$true } elseif ($attempt -lt 3) { Start-Sleep -Seconds 10 }
  }
  if (-not $ok) { throw "Failed to rerun workflow $($run.databaseId) after 3 attempts." }
}
gh pr checks $pr -R $repo --watch --fail-fast; $checksExit=$LASTEXITCODE
[pscustomobject]@{PendingRuns=$pending.Count;ChecksExit=$checksExit} | ConvertTo-Json
exit $checksExit","description":"Approve and watch PR checks","initial_wait":600,"mode":"sync","shellId":"workflowgate"}
